using Bancoficticio.Transferencias.Domain.Model;
using Bancoficticio.Transferencias.Domain.Port;
using Bancoficticio.Transferencias.Infrastructure;
using Microsoft.Data.SqlClient;

namespace Bancoficticio.Transferencias.Adapters.Out.Sql;

public sealed class SqlTransferenciaRepository(Db db) : TransferenciaRepository
{
    public int NextNumero()
    {
        using var command = db.Command("SELECT ISNULL(MAX(trf_numero), 0) + 1 FROM transferencias");
        var result = command.ExecuteScalar();
        return result is null || result is DBNull ? 1 : Convert.ToInt32(result);
    }

    public void Insert(int? numero, string? origen, string? destino, decimal? monto, decimal? comision, string? tipo)
    {
        using var command = db.Command(
            "INSERT INTO transferencias (trf_numero, trf_origen, trf_destino, trf_monto, trf_comision, trf_tipo) " +
            "VALUES (@numero, @origen, @destino, @monto, @comision, @tipo)");
        command.Parameters.AddWithValue("@numero", (object?)numero ?? DBNull.Value);
        command.Parameters.AddWithValue("@origen", (object?)origen ?? DBNull.Value);
        command.Parameters.AddWithValue("@destino", (object?)destino ?? DBNull.Value);
        command.Parameters.AddWithValue("@monto", (object?)monto ?? DBNull.Value);
        command.Parameters.AddWithValue("@comision", (object?)comision ?? DBNull.Value);
        command.Parameters.AddWithValue("@tipo", (object?)tipo ?? DBNull.Value);
        command.ExecuteNonQuery();
    }

    public Transferencia? FindByNumero(int? numero)
    {
        using var command = db.Command(
            "SELECT trf_numero, trf_origen, trf_destino, trf_monto, trf_comision, trf_tipo " +
            "FROM transferencias WHERE trf_numero = @numero");
        command.Parameters.AddWithValue("@numero", (object?)numero ?? DBNull.Value);
        using var reader = command.ExecuteReader();
        if (!reader.Read())
        {
            return null;
        }

        return new Transferencia(
            reader.IsDBNull(0) ? null : reader.GetInt32(0),
            reader.IsDBNull(1) ? null : reader.GetString(1),
            reader.IsDBNull(2) ? null : reader.GetString(2),
            reader.IsDBNull(3) ? null : reader.GetDecimal(3),
            reader.IsDBNull(4) ? null : reader.GetDecimal(4),
            reader.IsDBNull(5) ? null : reader.GetString(5));
    }
}
